 const booking=$('#booking-form');if(booking){const update=()=>{const q=Number(booking.elements.quantity.value);const lines=quote(booking.dataset.hotel,booking.dataset.room,model.search.start,model.search.end,Number.isInteger(q)&&q>0?q:1);$('#quote-lines').innerHTML=lines.map(l=>kv(shortDate(l.date)+' · '+l.quantity+' 间',money(l.price*l.quantity))).join('');$('#quote-total').textContent=money(quoteTotal(lines));};const remember=()=>{const f=new FormData(booking);model.bookingDraft={key:[booking.dataset.hotel,booking.dataset.room,model.search.start,model.search.end,model.search.guests].join('/'),guest:f.get('guest'),phone:f.get('phone'),quantity:Number(f.get('quantity')),agree:!!f.get('agree')};save();};booking.oninput=()=>{remember();update();};booking.onchange=remember;booking.onsubmit=e=>{e.preventDefault();remember();if(!model.user){returnTo=location.hash.slice(1);go('login');return;}const f=new FormData(booking);const hid=booking.dataset.hotel,rid=booking.dataset.room,q=Number(f.get('quantity')),s=model.search;if(!validGuestCount(s.guests)||!Number.isInteger(q)||q<roomsNeeded(room(hid,rid))||available(hid,rid,s.start,s.end)<q)return $('#booking-error').textContent='请核对房间数量：须容纳全部住客，且不能超过所选日期的可订房量。';const amount=quoteTotal(quote(hid,rid,s.start,s.end,q));const o=createOrder({hotel:hid,room:rid,start:s.start,end:s.end,quantity:q,guestCount:s.guests,guest:f.get('guest').trim(),phone:f.get('phone').trim(),owner:'guest',channel:'online',amount});delete model.bookingDraft;save();go('order/'+o.id);toast('模拟付款成功，等待酒店确认');};}
 const off=$('#offline-form');if(off)off.onsubmit=e=>{e.preventDefault();const f=new FormData(off),rid=f.get('room'),start=f.get('start'),end=f.get('end'),quantity=Number(f.get('quantity'));if(!validDates(start,end)||!Number.isInteger(quantity)||quantity<1)return $('#offline-error').textContent='请填写有效住宿日期与正整数房间数。';if(available('h1',rid,start,end)<quantity)return $('#offline-error').textContent='所选日期房量不足。';const amount=quoteTotal(quote('h1',rid,start,end,quantity).map(l=>({...l,price:f.get('student')?Math.round(l.price*80)/100:l.price})));modal('核对线下订房',kv('联系人',esc(f.get('guest')))+kv('日期',start+' — '+end)+kv('校园卡优惠',f.get('student')?'已核验 · 公开价八折':'不适用')+kv('应付金额',`<strong class="price">${money(amount)}</strong>`)+`<div class="modal-actions">${btn('返回修改','close-modal','secondary')}<button class="btn" id="offline-commit">模拟收款并确认</button></div>`,m=>$('#offline-commit',m).onclick=()=>{if(available('h1',rid,start,end)<quantity)return toast('房量发生变化，请重新查询');const o=createOrder({hotel:'h1',room:rid,start,end,quantity,guest:f.get('guest').trim(),phone:f.get('phone'),owner:'offline',channel:'offline',amount});o.status='confirmed';o.events.push('线下订房已确认');log('线下确认',o.id);cancelUnavailable('h1',rid);save();$('#modal').close();staffTab='all';go('staff/orders');toast('线下订单已确认');});};
 const cat=$('#catalog-form');if(cat)cat.onsubmit=e=>{e.preventDefault();const f=new FormData(cat);model.requests.unshift({id:'CH'+String(model.requests.length+1).padStart(3,'0'),kind:'资料',text:'梧桐院介绍与设施更新',status:'review',payload:{description:f.get('description').trim(),facilities:f.get('facilities').trim()}});log('提交资料审核',model.requests[0].id);save();render();toast('已提交，审核前对外资料不变');};
 const inv=$('#inventory-form');if(inv)inv.onsubmit=e=>{e.preventDefault();const f=new FormData(inv);const p={room:f.get('room'),day:f.get('day'),capacity:Number(f.get('capacity')),price:Number(f.get('price')),stopped:!!f.get('stopped')};if(p.day<date(0)||!Number.isInteger(p.capacity)||p.capacity<0)return $('#inventory-error').textContent='请核对日期和非负整数容量。';model.requests.unshift({id:'CH'+String(model.requests.length+1).padStart(3,'0'),kind:'库存价格',text:`${p.day} · 容量 ${p.capacity} · ${money(p.price)}${p.stopped?' · 停售':''}`,status:'review',payload:p});log('提交房量价格审核',model.requests[0].id);save();toast('变更已提交，可在平台审核工作区处理');};
 const fee=$('#fee-form');if(fee)fee.onsubmit=e=>{e.preventDefault();model.fee=Number(new FormData(fee).get('fee'));log('更新费率','梧桐院');save();toast('演示费率已保存');};
 const global=$('#global-filter');if(global)global.onsubmit=e=>{e.preventDefault();const f=new FormData(global),from=f.get('from'),to=f.get('to');if(from&&to&&from>to)return $('#global-error').textContent='开始日期不能晚于结束日期。';$('#global-error').textContent='';const list=model.orders.filter(o=>(f.get('hotel')==='all'||o.hotel===f.get('hotel'))&&(f.get('status')==='all'||o.status===f.get('status'))&&(!from||o[f.get('dateType')]>=from)&&(!to||o[f.get('dateType')]<=to)&&(!f.get('query')||(o.id+' '+o.guest).includes(f.get('query'))));$('#global-results').innerHTML=table(['订单 / 联系人','房源','日期','实付','状态','操作'],orderRows(list,true));};
 const incident=$('#incident-form');if(incident)incident.onsubmit=e=>{e.preventDefault();const f=new FormData(incident);const rid=f.get('room'),start=f.get('start'),end=f.get('end');if(!validDates(start,end))return $('#incident-error').textContent='请填写有效的影响日期区间。';const impacted=model.orders.filter(o=>o.hotel==='h1'&&o.room===rid&&o.start<end&&start<o.end&&['pending','confirmed','occupied'].includes(o.status));modal('核对无法接待的订单',`<p>${room('h1',rid).name} · ${start} — ${end}</p>${table(['订单','状态','处置'],impacted.map(o=>[o.id,badge(o.status),o.status==='occupied'?'登记人工处置':'取消并全额模拟退款']))}${note('确认后该房型对应日期停售。前台须在系统外电话通知，已入住订单保留人工处置。','danger')}<div class="modal-actions">${btn('返回','close-modal','secondary')}<button class="btn danger" id="incident-commit">确认停售并处理</button></div>`,m=>$('#incident-commit',m).onclick=()=>{const current=model.orders.filter(o=>o.hotel==='h1'&&o.room===rid&&o.start<end&&start<o.end&&['pending','confirmed','occupied'].includes(o.status));const entry={hotel:'h1',room:rid,start,end,reason:f.get('reason').trim(),count:0,manual:0};model.incidents.push(entry);for(const o of current){if(o.status==='occupied')entry.manual++;else {cancelOrder(o,'酒店原因无法接待',o.amount);entry.count++;}}log('应急停售',start+' 至 '+end);save();$('#modal').close();render();toast('已停售，退款与人工处置记录已更新');});};
